<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0a0a1a;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    font-family: 'Courier New', monospace;
    color: #00ff88;
    user-select: none;
  }
  #score {
    font-size: 22px;
    margin-bottom: 12px;
    letter-spacing: 2px;
    text-shadow: 0 0 10px #00ff88;
  }
  #snake {
    width: 400px;
    height: 400px;
    border: 2px solid #00ff88;
    border-radius: 6px;
    display: block;
    background: #0d0d2b;
    outline: none;
    box-shadow: 0 0 20px rgba(0,255,136,0.15);
  }
  .controls {
    margin-top: 14px;
    display: flex;
    gap: 10px;
  }
  button {
    background: #1a1a3e;
    color: #00ff88;
    border: 1px solid #00ff88;
    padding: 8px 22px;
    font-family: 'Courier New', monospace;
    font-size: 14px;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.2s;
  }
  button:hover {
    background: #00ff88;
    color: #0a0a1a;
  }
  button:active {
    transform: scale(0.96);
  }
</style>
</head>
<body>

<div id="score">Score: 0</div>
<canvas id="snake" width="400" height="400" tabindex="0"></canvas>
<div class="controls">
  <button id="start">Start</button>
  <button id="pause">Pause</button>
  <button id="reset">Reset</button>
</div>

<script>
(function() {
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');

  const W = 20;
  const H = 20;
  const CELL = 20;

  let snake = [];
  let food = [0, 0];
  let dir = 'right';
  let nextDir = 'right';
  let score = 0;
  let alive = false;
  let running = false;
  let interval = null;

  const opp = { up:'down', down:'up', left:'right', right:'left' };

  function updateScore() {
    document.getElementById('score').textContent = 'Score: ' + score;
  }

  function placeFood() {
    const occupied = new Set();
    snake.forEach(s => occupied.add(s[0] + ',' + s[1]));
    let x, y;
    do {
      x = Math.floor(Math.random() * W);
      y = Math.floor(Math.random() * H);
    } while (occupied.has(x + ',' + y));
    food = [x, y];
  }

  function draw() {
    ctx.fillStyle = '#0d0d2b';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Grid lines
    ctx.strokeStyle = '#1a1a3e';
    ctx.lineWidth = 0.5;
    for (let x = 0; x <= W; x++) {
      ctx.beginPath();
      ctx.moveTo(x * CELL + 0.5, 0);
      ctx.lineTo(x * CELL + 0.5, canvas.height);
      ctx.stroke();
    }
    for (let y = 0; y <= H; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL + 0.5);
      ctx.lineTo(canvas.width, y * CELL + 0.5);
      ctx.stroke();
    }

    // Food
    ctx.save();
    ctx.fillStyle = '#ff3366';
    ctx.shadowColor = '#ff3366';
    ctx.shadowBlur = 15;
    ctx.beginPath();
    ctx.arc(food[0] * CELL + CELL / 2, food[1] * CELL + CELL / 2, CELL / 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // Snake body
    const len = snake.length;
    snake.forEach((seg, i) => {
      const t = len > 1 ? i / (len - 1) : 0;
      const g = Math.floor(255 * (1 - t * 0.6));
      const b = Math.floor(136 * (1 - t * 0.4));
      ctx.fillStyle = 'rgb(0,' + g + ',' + b + ')';
      const p = 1.5;
      ctx.fillRect(seg[0] * CELL + p, seg[1] * CELL + p, CELL - p * 2, CELL - p * 2);
    });

    // Snake head (brighter with glow)
    if (len > 0) {
      ctx.save();
      ctx.fillStyle = '#00ffaa';
      ctx.shadowColor = '#00ffaa';
      ctx.shadowBlur = 8;
      const head = snake[0];
      const p = 1.5;
      ctx.fillRect(head[0] * CELL + p, head[1] * CELL + p, CELL - p * 2, CELL - p * 2);
      ctx.restore();
    }

    // Overlays
    if (!alive) {
      ctx.fillStyle = 'rgba(0,0,0,0.75)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff3366';
      ctx.font = 'bold 32px Courier New';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('GAME OVER', canvas.width / 2, canvas.height / 2 - 18);
      ctx.fillStyle = '#00ff88';
      ctx.font = '18px Courier New';
      ctx.fillText('Score: ' + score, canvas.width / 2, canvas.height / 2 + 18);
    } else if (!running && len > 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.4)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#00ff88';
      ctx.font = '16px Courier New';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('PAUSED', canvas.width / 2, canvas.height / 2);
    } else if (len === 0) {
      ctx.fillStyle = '#00ff88';
      ctx.font = '16px Courier New';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('Press Start', canvas.width / 2, canvas.height / 2);
    }
  }

  const game = {
    w: W,
    h: H,

    reset() {
      const sx = Math.floor(W / 2);
      const sy = Math.floor(H / 2);
      snake = [
        [sx, sy],
        [sx - 1, sy],
        [sx - 2, sy]
      ];
      dir = 'right';
      nextDir = 'right';
      score = 0;
      alive = true;
      running = false;
      clearInterval(interval);
      interval = null;
      placeFood();
      updateScore();
      draw();
    },

    tick() {
      if (!alive) return;

      dir = nextDir;

      const head = snake[0];
      let nh = [head[0], head[1]];
      switch (dir) {
        case 'up':    nh[1]--; break;
        case 'down':  nh[1]++; break;
        case 'left':  nh[0]--; break;
        case 'right': nh[0]++; break;
      }

      // Wall collision
      if (nh[0] < 0 || nh[0] >= W || nh[1] < 0 || nh[1] >= H) {
        alive = false;
        draw();
        return;
      }

      // Self collision
      const willGrow = (nh[0] === food[0] && nh[1] === food[1]);
      const checkLen = willGrow ? snake.length : snake.length - 1;
      for (let i = 0; i < checkLen; i++) {
        if (snake[i][0] === nh[0] && snake[i][1] === nh[1]) {
          alive = false;
          draw();
          return;
        }
      }

      snake.unshift(nh);

      if (willGrow) {
        score++;
        updateScore();
        placeFood();
      } else {
        snake.pop();
      }

      draw();
    },

    setDir(d) {
      if (opp[d] === dir) return;
      nextDir = d;
    },

    setFood(x, y) {
      food = [x, y];
      draw();
    },

    snake() {
      return snake.map(s => [s[0], s[1]]);
    },

    food() {
      return [food[0], food[1]];
    },

    alive() {
      return alive;
    },

    score() {
      return score;
    }
  };

  window.game = game;

  document.getElementById('start').addEventListener('click', () => {
    if (!running && alive) {
      running = true;
      interval = setInterval(() => game.tick(), 150);
    }
  });

  document.getElementById('pause').addEventListener('click', () => {
    running = false;
    clearInterval(interval);
    interval = null;
    draw();
  });

  document.getElementById('reset').addEventListener('click', () => {
    running = false;
    clearInterval(interval);
    interval = null;
    game.reset();
  });

  document.addEventListener('keydown', (e) => {
    switch (e.key) {
      case 'ArrowUp':    game.setDir('up');    e.preventDefault(); break;
      case 'ArrowDown':  game.setDir('down');  e.preventDefault(); break;
      case 'ArrowLeft':  game.setDir('left');  e.preventDefault(); break;
      case 'ArrowRight': game.setDir('right'); e.preventDefault(); break;
    }
  });

  game.reset();
})();
</script>

</body>
</html>
